package com.amit.jobagent.matching;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;
@Component public class EvaluationRequirementProvider{private final JdbcTemplate jdbc;public EvaluationRequirementProvider(JdbcTemplate j){jdbc=j;}public List<RequirementView>forEvaluation(UUID evaluationId){return jdbc.query("SELECT id,requirement_text,requirement_type,category,match_status,job_evidence FROM job_agent.job_evaluation_requirement WHERE evaluation_id=? ORDER BY created_at,id",(rs,n)->new RequirementView(rs.getObject("id",UUID.class),rs.getString("requirement_text"),rs.getString("requirement_type"),rs.getString("category"),rs.getString("match_status"),rs.getString("job_evidence")),evaluationId);}public record RequirementView(UUID id,String text,String type,String category,String matchStatus,String jobEvidence){}}
